            ("ctrl-tab", 2, 2.),
            ("ctrl-tab", 3, 3.),
            ("ctrl-tab", 0, 4.),
            ("ctrl-tab", 1, 5.),
            ("ctrl-shift-tab", 0, 4.),
            ("ctrl-shift-tab", 3, 3.),
            ("ctrl-shift-tab", 2, 2.),
            ("ctrl-shift-tab", 1, 1.),
            ("ctrl-shift-tab", 0, 0.),
            ("ctrl-shift-tab", 3, -1.),
        ];
        for (key, expected, tint_target) in presses {
            cx.update_window(handle, |_, window, cx| window.press(key, cx))
                .unwrap();
            cx.run_until_parked();
            cx.update_window(handle, |_, window, cx| {
