214	    /// Each reference to an imported name in `prompt`, then in the system
215	    /// prompt, once, in the order they first appear.
216	    fn references<'a>(&'a self, prompt: &'a str) -> Vec<&'a str> {
217	        let mut references = Vec::new();
218	        for text in std::iter::once(prompt).chain(self.system_prompt.as_deref()) {
219	            for piece in pieces(text) {
220	                if let Piece::Reference(reference, name) = piece
221	                    && self.imports.has(name)
222	                    && !references.contains(&reference)
