374	/// Adds `text` to `source` as a multi-line escape block at `indent`, which
375	/// Piton keeps exactly as it is. Its fence is three backslashes, or one more
376	/// than any line of the text made only of backslashes, so nothing in the text
377	/// closes it early.
378	fn push_block(source: &mut String, indent: &str, text: &str) {
379	    let fence = "\\".repeat(fence_length(text));
380	    writeln!(source, "{indent}{fence}").ok();
381	    for line in text.split('\n') {
382	        let line = line.trim_end_matches('\r');
383	        if line.is_empty() {
384	            source.push('\n');
385	        } else {
386	            writeln!(source, "{indent}{line}").ok();
387	        }
388	    }
389	    writeln!(source, "{indent}{fence}").ok();
390	}
